create or replace function app.list_finance_invoice_margin_summaries(p_limit integer default 200)
returns table(invoice_id uuid,estimated_hpp numeric,estimated_margin numeric,estimated_margin_percent numeric,net_cash_revenue numeric,actual_direct_cost numeric,total_linked_cost numeric,actual_margin numeric,actual_margin_percent numeric,hpp_variance numeric)
language plpgsql stable security definer set search_path='' as $$begin if not(app.has_permission('finance_invoices.create') or app.has_permission('finance_expenses.record') or app.has_permission('financial_reports.view')) then raise exception 'Missing finance permission.' using errcode='42501';end if;return query with inv as(select i.id,i.grand_total,i.paid_total,i.refunded_total from public.finance_invoices i order by i.created_at desc limit least(greatest(coalesce(p_limit,200),1),500)),est as(select ii.invoice_id,coalesce(sum(coalesce(ii.estimated_cost_total,coalesce(ii.estimated_unit_cost,0)*ii.quantity)),0) estimated_hpp from public.finance_invoice_items ii join inv on inv.id=ii.invoice_id group by ii.invoice_id),cost as(select e.invoice_id,coalesce(sum(e.total_amount) filter(where e.cost_class='direct_cost'),0) direct_cost,coalesce(sum(e.total_amount),0) total_cost from public.finance_expenses e join inv on inv.id=e.invoice_id where e.status='recorded' group by e.invoice_id) select i.id,coalesce(e.estimated_hpp,0),i.grand_total-coalesce(e.estimated_hpp,0),case when i.grand_total>0 then round(((i.grand_total-coalesce(e.estimated_hpp,0))/i.grand_total)*100,2) else 0 end,greatest(i.paid_total-i.refunded_total,0),coalesce(c.direct_cost,0),coalesce(c.total_cost,0),greatest(i.paid_total-i.refunded_total,0)-coalesce(c.total_cost,0),case when greatest(i.paid_total-i.refunded_total,0)>0 then round(((greatest(i.paid_total-i.refunded_total,0)-coalesce(c.total_cost,0))/greatest(i.paid_total-i.refunded_total,0))*100,2) else 0 end,coalesce(c.direct_cost,0)-coalesce(e.estimated_hpp,0) from inv i left join est e on e.invoice_id=i.id left join cost c on c.invoice_id=i.id;end$$;revoke all on function app.list_finance_invoice_margin_summaries(integer) from public,anon;grant execute on function app.list_finance_invoice_margin_summaries(integer) to authenticated;